+void MainWindowPreferencesFrame::on_scrollBarExtentSyntaxEdit_textEdited(const QString &new_str)
+{
+    unsigned new_uint;
+    if (new_str.isEmpty()) {
+        new_uint = prefs_get_uint_value(pref_scrollbar_extent_, pref_default);
+        prefs_set_uint_value(pref_scrollbar_extent_, new_uint, pref_stashed);
+        ui->scrollBarExtentSyntaxEdit->setSyntaxState(SyntaxLineEdit::Empty);
+        return;
+    }
+
+    bool ok;
+    new_uint = new_str.toUInt(&ok, 0);
+    if (ok) {
+        ui->scrollBarExtentSyntaxEdit->setSyntaxState(SyntaxLineEdit::Valid);
+    } else {
+        new_uint = prefs_get_uint_value(pref_scrollbar_extent_, pref_current);
+        ui->scrollBarExtentSyntaxEdit->setSyntaxState(SyntaxLineEdit::Invalid);
+    }
+    prefs_set_uint_value(pref_scrollbar_extent_, new_uint, pref_stashed);
+}
